module ActiveSupport;class BacktraceCleaner;def initialize;@filters,@silencers=[],[];add_core_silencer;add_gem_filter;add_gem_silencer;add_stdlib_silencer;end;def clean(backtrace,kind=:silent)filtered=filter_backtrace(backtrace);case kind;when :silent;silence(filtered);when :noise;noise(filtered);else filtered;end;end;alias :filter:clean;def clean_frame(frame,kind=:silent)frame=frame.to_s;@filters.each do |f|frame=f.call(frame.to_s);end;case kind;when :silent;frame unless @silencers.any?{|s|s.call(frame)};when :noise;frame if @silencers.any?{|s|s.call(frame)};else frame;end;end;def add_filter(&block)@filters<<block;end;def add_silencer(&block)@silencers<<block;end;def remove_silencers!;@silencers=[];end;def remove_filters!;@filters=[];end;private;FORMATTED_GEMS_PATTERN=/\A[^\/]+ \([\w.]+\) /;def initialize_copy(_other)@filters=@filters.dup;@silencers=@silencers.dup;end;def add_gem_filter;gems_paths=(Gem.path|[Gem.default_dir]).map{|p|Regexp.escape(p)};return if gems_paths.empty?;gems_regexp= %r{\A(#{gems_paths.join('|')})/(bundler/)?gems/([^/]+)-([\w.]+)/(.*)};gems_result='\3 (\4) \5';add_filter{|line|line.sub(gems_regexp,gems_result)};end;def add_core_silencer;add_silencer{|line|line.include?("<internal:")};end;def add_gem_silencer;add_silencer{|line|FORMATTED_GEMS_PATTERN.match?(line)};end;def add_stdlib_silencer;add_silencer{|line|line.start_with?(RbConfig::CONFIG["rubylibdir"])};end;def filter_backtrace(backtrace)@filters.each do |f|backtrace=backtrace.map{|line|f.call(line.to_s)};end;backtrace;end;def silence(backtrace)@silencers.each do |s|backtrace=backtrace.reject{|line|s.call(line.to_s)};end;backtrace;end;def noise(backtrace)backtrace.select do |line|@silencers.any? do |s|s.call(line.to_s);end;end;end;end;end
